from lib import *
S = SS('l37')
steps = [
    step("基线:60 个模块目录,每个 500 个文件,加根目录 README.md 和 Makefile,共 30,002 个文件。完整检出时 index 是 2,651,434 字节,git status 62.2 ms。", t=tl(S(1)), mark=lidx(S(1), '30,002'), done=lidx(S(1), 'index 2,651,434'), kv=KV([['文件数', '30,002'], ['index', '2.65 MB'], ['git status', '62.2 ms']], ['文件数'])),
    step("git sparse-checkout init --cone 再 set mod05 mod06:工作区 ls 只剩 Makefile、README.md、mod05、mod06,文件数从 30,002 降到 1,002。cone 模式把 mod05、mod06 写成 .git/info/sparse-checkout 里的四行:/*(根目录的文件)、!/*/(排除所有一级目录)、/mod05/、/mod06/(把这两个目录加回来);配置里 core.sparsecheckout = true 和 core.sparsecheckoutcone = true。", t=tl(S(2)), mark=lidx(S(2), '/*', '!/*/', '/mod05/', '/mod06/'), done=lidx(S(2), 'Makefile', 'mod05', 'mod06', 'core.sparsecheckout true', '1,002'), kv=KV([['cone 模式', '按目录,模式只有 4 行'], ['/* 与 !/*/', '根目录文件保留,一级子目录先全部排除'], ['/mod05/', '再把想要的目录加回来']], ['cone 模式'])),
    step("没检出的文件仍在 index 里,只是带 skip-worktree 标记:git ls-files -t 统计 1002 个 H(正常)和 29000 个 S(skip-worktree),例如 S mod00/sub0/f0000.txt。index 仍是 2,651,434 字节,包含全部 30,002 个条目。但 git status 从 62.2 ms 降到 18.2 ms——S 标记的条目不用 lstat。", t=tl(S(3)), mark=lidx(S(3), '29000 S', 'S mod00', 'git status 18.2'), done=lidx(S(3), '1002 H'), b=bars([['完整检出', 62.2, '62.2 ms'], ['cone,完整 index', 18.2, '18.2 ms']], 62.2, mark=[1], done=[0]), kv=KV([['S 标记', 'skip-worktree:不检出,不 lstat'], ['index 条目', '仍有 30,002 个'], ['git status', '62.2 → 18.2 ms']], ['S 标记'])),
    step("稀疏索引 git sparse-checkout init --cone --sparse-index(index.sparse = true):index 缩到 94,511 字节、1,060 个条目(原来 30,002 个),扩展块多了 sdir;没检出的目录(58 个)在 index 里只留一个目录条目(模式 040000),例如 mod00/,不再列出里面的 500 个文件。git ls-files --sparse 数出 1060,git ls-files(展开)数出 30002。这个规模下 git status 17.4 ms,与上一步的 18.2 ms 基本相同——稀疏索引省的是 index 的大小和读写,不是 lstat。", t=tl(S(4)), mark=lidx(S(4), '94,511', 'mod00/', 'sdir', '58 个', '1060'), done=lidx(S(4), 'index.sparse', 'true', '30002', 'git status'), b=bars([['完整 index', 2651434, '2,651,434 字节'], ['稀疏 index', 94511, '94,511 字节']], 2651434, mark=[1], done=[0]), kv=KV([['稀疏目录条目', '一个 040000 条目代替整个目录'], ['index', '2.65 MB → 94.5 KB'], ['展开', 'git ls-files 会临时展开']], ['稀疏目录条目'])),
    step("越出稀疏范围的操作:git add mod20(范围外)输出 The following paths and/or pathspecs matched paths that exist outside of your sparse-checkout definition, so will not be updated in the index: mod20,拒绝更新。手工在范围外创建 mod20/outside.txt,git status 仍然报告 ?? mod20/outside.txt,并提示 The sparse index is expanding to a full index, a slow operation.(需要展开稀疏索引才能处理这个路径)。git sparse-checkout add mod20 把 mod20 加进范围,ls 里出现 mod20。", t=tl(S(5)), mark=lidx(S(5), 'outside of your sparse-checkout', '?? mod20/outside.txt', 'sparse index is expanding'), done=lidx(S(5), 'Makefile README.md mod05 mod06 mod20'), kv=KV([['范围外 add', '被拒绝,提示 outside of your sparse-checkout definition'], ['范围外的新文件', '仍报告为未跟踪,并展开稀疏索引'], ['扩大范围', 'git sparse-checkout add <目录>']], ['范围外 add'])),
    step("git sparse-checkout disable 恢复全部:ls 数出 62 项(60 个模块目录加 2 个根文件),工作区文件数回到 30,002,index 回到 2,651,434 字节,git status 回到 61.5 ms。稀疏检出是纯本地的视图,对象库里一直有全部内容。", t=tl(S(6)), mark=lidx(S(6), '62'), done=lidx(S(6), 'git sparse-checkout disable', '30,002'), kv=KV([['disable', '恢复完整工作区'], ['对象库', '一直是完整的'], ['区别于 partial clone', 'partial clone 才是少下载对象']], ['对象库'])),
]
A = mkarti('l37', 37, 'Git,sparse-checkout,cone,sparse index,skip-worktree,真实验证,动画演示',
    '在 30,002 个文件的仓库上实测 sparse-checkout:cone 模式把工作区缩到 1,002 个文件,.git/info/sparse-checkout 只有 4 行;没检出的 29000 个文件仍在 index 里带 skip-worktree 标记,git status 从 62.2 ms 降到 18.2 ms;稀疏索引把 index 从 2,651,434 字节压到 94,511 字节(1,060 个条目,58 个目录条目);范围外的 add 被拒绝;disable 恢复全部。',
    'sparse-checkout 让大仓库只检出一部分目录。这篇在 3 万个文件的仓库上看它在 .git 里做了什么:cone 模式的那 4 行模式、index 里的 skip-worktree 标记、稀疏索引怎么把 index 缩小 28 倍,以及越出范围时的行为。',
    [('30,002 → 1,002', 'cone 模式 sparse-checkout 之后工作区的文件数'), ('2.65 MB → 94.5 KB', '稀疏索引把 index 缩小的幅度(1,060 个条目)'), ('62 → 18 ms', 'cone 模式下 git status 的耗时(skip-worktree 的文件不用 lstat)')],
    [('基线', '<p>完整检出时每个文件都要 lstat,index 记录全部条目。</p>'),
     ('cone 模式', '<p><code>git sparse-checkout init --cone</code> 加 <code>set 目录…</code> 在 <code>.git/info/sparse-checkout</code> 里写成 <code>/*</code>、<code>!/*/</code> 加每个目录的 <code>/dir/</code>,即“根目录的文件 + 选中的目录”;同时设置 <code>core.sparseCheckout</code> 与 <code>core.sparseCheckoutCone</code>。cone 模式匹配简单、快。</p>'),
     ('skip-worktree', '<p>没检出的文件仍在 index 里,带 skip-worktree 标记(<code>git ls-files -t</code> 里显示 S)。git 不为它们 lstat,所以 <code>git status</code> 变快。对象库里仍有全部内容——这不是 partial clone。</p>'),
     ('稀疏索引', '<p>稀疏索引(<code>--sparse-index</code>)进一步把整个没检出的目录在 index 里合成一个 040000 的“目录条目”(<code>sdir</code> 扩展),index 从 2.65 MB 缩到 94.5 KB。读写 index 更快,内存更小;需要看目录内部时会临时展开。</p>'),
     ('范围外', '<p>对范围外路径 <code>git add</code> 会被拒绝并提示;在范围外手工创建的文件仍被报告为未跟踪,并提示稀疏索引正在展开。要改变范围用 <code>sparse-checkout add</code>。</p>'),
     ('恢复', '<p><code>sparse-checkout disable</code> 把所有文件检出回来,index 恢复完整。</p>')],
    steps,
    [ENV_I_GIT + '。仓库由脚本生成(60 个模块 × 500 个文件);耗时 5 次中位数,含进程启动,每次测量前先让 index 刷新(避开 racy 窗口);index 字节数与条目数来自 .git/index 本身',
     '没有验证:非 cone 模式(gitignore 风格模式)的匹配与性能;partial clone 配合 sparse-checkout(下载更少对象,见后面 partial clone 一篇);sparse-checkout 下切换分支、合并时遇到范围外冲突的行为;更大规模(十万、百万文件)下稀疏索引对 status/add 的加速;git sparse-checkout clean / reapply'],
    'sparse-checkout')
